def solve(tokens):
    """Evaluate Reverse Polish Notation expression.
    tokens: list of strings, each either an integer or an operator '+', '-', '*', '/'.
    Returns the integer result with division truncating toward zero.
    """
    stack = []
    for token in tokens:
        if token in ('+', '-', '*', '/'):
            b = stack.pop()
            a = stack.pop()
            if token == '+':
                stack.append(a + b)
            elif token == '-':
                stack.append(a - b)
            elif token == '*':
                stack.append(a * b)
            else:  # division
                # Python's int() truncates toward zero for float division
                # Using int(a / b) handles negative values correctly.
                stack.append(int(a / b))
        else:
            stack.append(int(token))
    return stack[0] if stack else 0

