    """Return length of the longest strictly increasing subsequence.
    Handles any iterable of comparable items. Returns 0 for None or empty.
    """
    # Guard against None or non-iterable inputs
    if arr is None:
        return 0
    try:
        seq = list(arr)
    except TypeError:
        return 0
    if not seq:
        return 0
    import bisect
    tails = []  # tails[i] is the minimum possible tail of an inc subseq of length i+1
    for x in seq:
        # Find position to replace in tails (strictly increasing, so use bisect_left)
        i = bisect.bisect_left(tails, x)
        if i == len(tails):
            tails.append(x)
        else:
            tails[i] = x
    return len(tails)"}

