def solve(grid):
    """Count islands in a binary grid.
    Handles non‑rectangular grids and empty rows gracefully.
    Uses a set for visited cells.
    """
    if not grid:
        return 0
    rows = len(grid)
    visited = set()
    def dfs(r, c):
        stack = [(r, c)]
        while stack:
            i, j = stack.pop()
            if (i, j) in visited:
                continue
            visited.add((i, j))
            # explore 4-directional neighbours
            for di, dj in ((1,0),(-1,0),(0,1),(0,-1)):
                ni, nj = i+di, j+dj
                if 0 <= ni < rows:
                    # ensure column index is within that row's length
                    if 0 <= nj < len(grid[ni]) and grid[ni][nj] == 1:
                        stack.append((ni, nj))
    count = 0
    for i, row in enumerate(grid):
        for j, val in enumerate(row):
            if val == 1 and (i, j) not in visited:
                dfs(i, j)
                count += 1
    return count

