def solve(a, b):
    # classic DP for Levenshtein distance
    n, m = len(a), len(b)
    # ensure the smaller dimension for space optimization
    if n < m:
        a, b = b, a
        n, m = m, n
    # now n >= m
    previous = list(range(m + 1))
    for i in range(1, n + 1):
        current = [i] + [0] * m
        for j in range(1, m + 1):
            if a[i - 1] == b[j - 1]:
                cost = 0
            else:
                cost = 1
            current[j] = min(
                previous[j] + 1,      # deletion
                current[j - 1] + 1,   # insertion
                previous[j - 1] + cost  # substitution
            )
        previous = current
    return previous[m]

